<script setup>import { computed } from 'vue';import { useTaskStore } from '../stores/taskStore.js';import TaskList from '../components/task/TaskList.vue';const emit=defineEmits(['add-task','edit-task']);const s=useTaskStore();const todayOpen=computed(()=>s.dueToday.filter(t=>!t.completed));const completedToday=computed(()=>s.tasks.filter(t=>t.completedAt?.slice(0,10)===s.today))</script>
<template><div class="page"><section class="page-heading"><div><span class="eyebrow">Daily plan</span><h2>Today</h2><p>{{new Date().toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric'})}}</p></div><button class="primary-button" @click="$emit('add-task',null,s.today)">＋ Add for today</button></section><section v-if="s.overdue.length" class="task-section"><div class="section-header"><h2>Overdue <span class="count danger-bg">{{s.overdue.length}}</span></h2></div><TaskList :tasks="s.overdue" @edit="$emit('edit-task',$event)"/></section><section class="task-section"><div class="section-header"><h2>Due today <span class="count">{{todayOpen.length}}</span></h2></div><TaskList :tasks="todayOpen" empty-title="Today's clear" empty-message="Enjoy the breathing room or plan your next win." @add="$emit('add-task',null,s.today)" @edit="$emit('edit-task',$event)"/></section><section v-if="completedToday.length" class="task-section"><div class="section-header"><h2>Completed today <span class="count success-bg">{{completedToday.length}}</span></h2></div><TaskList :tasks="completedToday" compact @edit="$emit('edit-task',$event)"/></section></div></template>
